//! Contains search entity models

use thiserror::Error;

use crate::domain::models::{funder::Funder as FunderDetails, parliament_member::ParliamentMember};

const MAX_STRICTNESS: f32 = 1_f32;
const MIN_STRICTNESS: f32 = 0_f32;
const MIN_ENTRIES: u8 = 1;

#[derive(Clone, Debug, PartialEq, Eq)]
/// Search entity kind
pub enum Entity {
    /// Company entity
    Funder(FunderDetails),
    /// Member entitiy
    ParliamentMember(ParliamentMember),
}

impl Entity {
    #[must_use]
    /// Entity name
    pub fn name(&self) -> &str {
        match self {
            Self::Funder(kind) => kind.name(),
            Self::ParliamentMember(mp) => mp.name(),
        }
    }

    #[must_use]
    /// Entity kind
    pub const fn kind(&self) -> &str {
        match self {
            Self::Funder(_) => "Funder",
            Self::ParliamentMember(_) => "MP",
        }
    }

    #[must_use]
    /// Funder kind
    pub fn funder_kind(&self) -> Option<&str> {
        match self {
            Self::Funder(kind) => Some(kind.kind()),
            Self::ParliamentMember(_) => None,
        }
    }
}

impl From<&ParliamentMember> for Entity {
    fn from(value: &ParliamentMember) -> Self {
        Self::ParliamentMember(value.clone())
    }
}

impl From<&FunderDetails> for Entity {
    fn from(value: &FunderDetails) -> Self {
        Self::Funder(value.clone())
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
/// Search entity name
pub struct EntityName(String);

#[derive(Clone, Debug, PartialEq)]
/// Data required to search entities
pub struct EntitySearchRequest {
    term: String,
    strictness: f32,
    max_entries: u8,
}

impl EntitySearchRequest {
    #[must_use]
    /// Search term
    pub const fn term(&self) -> &str {
        self.term.as_str()
    }

    #[must_use]
    /// Search strictness
    pub const fn strictness(&self) -> f32 {
        self.strictness
    }

    #[must_use]
    /// Max result set
    pub const fn max_entries(&self) -> u8 {
        self.max_entries
    }
}

impl EntitySearchRequest {
    /// Creates new instance with [`MAX_STRICTNESS`]
    ///
    /// # Errors
    /// - See [`Self::new_with_strictness`]
    pub fn new_strict(term: String, max_entries: u8) -> Result<Self, EntitySearchError> {
        Self::new_with_strictness(term, max_entries, MAX_STRICTNESS)
    }
    /// Creates new instance with variable strictness
    ///
    /// # Errors
    /// - Term too short
    /// - Too few entries
    /// - Invalid strictness
    pub fn new_with_strictness(
        term: String,
        max_entries: u8,
        strictness: f32,
    ) -> Result<Self, EntitySearchError> {
        // It will be a u8
        #[allow(clippy::cast_possible_truncation)]
        if term.trim().len() < 3 {
            return Err(EntitySearchError::InvalidTerm(term.trim().len() as u8));
        }
        if max_entries < MIN_ENTRIES {
            return Err(EntitySearchError::TooFewEntries);
        }
        if strictness < MIN_STRICTNESS || strictness > MAX_STRICTNESS {
            return Err(EntitySearchError::InvalidStrictness(strictness));
        }
        Ok(Self {
            term,
            strictness,
            max_entries,
        })
    }
}

/// Errors related to entity search
#[derive(Error, Debug)]
pub enum EntitySearchError {
    /// Unexpected runtime errors, usually from the database
    #[error("unexpected error occurred: {0}")]
    UnexpectedError(String),

    /// Term too short for generating valid search results
    #[error("term must be at last three characters long; received {0}")]
    InvalidTerm(u8),

    /// Invalid strictness value
    #[error("at least one entry must be expected to return")]
    TooFewEntries,

    /// Invalid strictness value
    #[error("strictness must be between {MIN_STRICTNESS} and {MAX_STRICTNESS}; get {0}")]
    InvalidStrictness(f32),
}
//! Entity search refers to the landing page of the `exposed` application. Its purpose it to make it
//! easy for journalists to find [`parliament_members`] or [`funders`].
//!

mod error;
mod interface;

use crate::domain::models::entity_search::{Entity, EntitySearchError, EntitySearchRequest};
use crate::domain::models::funder::Funder;
use crate::domain::models::parliament_member::ParliamentMember;
use crate::domain::models::search_similarity::SearchSimilarity;
use crate::domain::repositories::funder_repository::FunderRepo;
use crate::domain::repositories::parliament_member_repository::ParliamentMemberRepo;
pub use crate::domain::services::entity_search::interface::EntitySearchService;

/// Allows users to search the databse using free text.
#[derive(Clone)]
pub struct Service<P, F> {
    mp_repo: P,
    funder_repo: F,
}

impl<P, F> Service<P, F> {
    /// Creates a new instance
    pub const fn new(mp_repo: P, funder_repo: F) -> Self {
        Self {
            mp_repo,
            funder_repo,
        }
    }
}

impl<P, F> EntitySearchService for Service<P, F>
where
    P: ParliamentMemberRepo,
    F: FunderRepo,
{
    /// Returns text search results for MPs and Funder entities.
    ///
    /// This function expects the repositories to return their results
    /// in order where a higher score means a higher similarity.
    async fn search_entities(
        &self,
        req: &EntitySearchRequest,
    ) -> Result<Vec<Entity>, EntitySearchError> {
        let mps = self.mp_repo.get_members_by_text_search_score(req).await?;
        let funders = self
            .funder_repo
            .get_funders_by_text_search_score(req)
            .await?;

        let scored = merge_scores(&mps, &funders);
        Ok(scored)
    }
}

/// Uses two-pointer technique to merge to pre-sorted
/// search results together.
fn merge_scores(
    mps: &[(ParliamentMember, SearchSimilarity)],
    funders: &[(Funder, SearchSimilarity)],
) -> Vec<Entity> {
    let mut scores = Vec::new();

    let (mut l, mut r) = (0, 0);
    // Unwrap acceptable as index check in
    // while function
    while l < mps.len() && r < funders.len() {
        let mp: &(ParliamentMember, SearchSimilarity) = mps.get(l).unwrap();
        let fund: &(Funder, SearchSimilarity) = funders.get(r).unwrap();

        match &mp.1.value().total_cmp(&fund.1.value()) {
            std::cmp::Ordering::Equal => {
                scores.push(Entity::from(&mp.0));
                scores.push(Entity::from(&fund.0));
                l += 1;
                r += 1;
            }
            std::cmp::Ordering::Greater => {
                scores.push(Entity::from(&mp.0));
                l += 1;
            }
            std::cmp::Ordering::Less => {
                scores.push(Entity::from(&fund.0));
                r += 1;
            }
        }
    }
    if l < mps.len() {
        for mp in &mps[l..] {
            scores.push(Entity::from(&mp.0));
        }
    }
    if r < funders.len() {
        for fund in &funders[r..] {
            scores.push(Entity::from(&fund.0));
        }
    }

    scores
}

#[cfg(test)]
mod merge_scores {
    use crate::domain::{
        models::{
            entity_search::Entity,
            funder::{Funder, FunderKind},
            parliament_member::ParliamentMember,
            search_similarity::SearchSimilarity,
        },
        services::entity_search::merge_scores,
    };

    #[test]
    fn works_for_only_mps() {
        let funders = Vec::new();
        let mps = vec![
            (
                ParliamentMember::new("johnny larner".into(), 1, String::new(), 1, String::new()),
                SearchSimilarity::from(1_f32),
            ),
            (
                ParliamentMember::new("hades".into(), 1, String::new(), 1, String::new()),
                SearchSimilarity::from(2_f32),
            ),
        ];

        let ranked = merge_scores(&mps, &funders);
        assert_eq!(
            ranked.first().unwrap(),
            &Entity::from(&ParliamentMember::new(
                "johnny larner".into(),
                1,
                String::new(),
                1,
                String::new(),
            ))
        );

        assert_eq!(
            ranked.get(1).unwrap(),
            &Entity::from(&ParliamentMember::new(
                "hades".into(),
                1,
                String::new(),
                1,
                String::new(),
            ))
        );
    }

    #[test]
    fn works_for_balanced_results() {
        let funders = vec![
            (
                Funder::new("heavenly ltd".into(), FunderKind::Company),
                SearchSimilarity::from(4_f32),
            ),
            (
                Funder::new("canna ltd".into(), FunderKind::Company),
                SearchSimilarity::from(2_f32),
            ),
        ];
        let mps = vec![
            (
                ParliamentMember::new("johnny larner".into(), 1, String::new(), 1, String::new()),
                SearchSimilarity::from(4_f32),
            ),
            (
                ParliamentMember::new("hades".into(), 1, String::new(), 1, String::new()),
                SearchSimilarity::from(3_f32),
            ),
        ];

        let ranked = merge_scores(&mps, &funders);
        assert_eq!(ranked.len(), 4);
        assert_eq!(
            ranked.first().unwrap(),
            &Entity::from(&ParliamentMember::new(
                "johnny larner".into(),
                1,
                String::new(),
                1,
                String::new(),
            ))
        );
        assert_eq!(
            ranked.get(1).unwrap(),
            &Entity::from(&Funder::new("heavenly ltd".into(), FunderKind::Company),)
        );
        assert_eq!(
            ranked.get(2).unwrap(),
            &Entity::from(&ParliamentMember::new(
                "hades".into(),
                1,
                String::new(),
                1,
                String::new(),
            ))
        );
        assert_eq!(
            ranked.get(3).unwrap(),
            &Entity::from(&Funder::new("canna ltd".into(), FunderKind::Company),)
        );
    }

    #[test]
    fn works_for_more_funders() {
        let funders = vec![
            (
                Funder::new("heavenly ltd".into(), FunderKind::Company),
                SearchSimilarity::from(4_f32),
            ),
            (
                Funder::new("canna ltd".into(), FunderKind::Company),
                SearchSimilarity::from(2_f32),
            ),
        ];
        let mps = vec![(
            ParliamentMember::new("johnny larner".into(), 1, String::new(), 1, String::new()),
            SearchSimilarity::from(4_f32),
        )];

        let ranked = merge_scores(&mps, &funders);
        assert_eq!(ranked.len(), 3);
        assert_eq!(
            ranked.first().unwrap(),
            &Entity::from(&ParliamentMember::new(
                "johnny larner".into(),
                1,
                String::new(),
                1,
                String::new(),
            ))
        );
        assert_eq!(
            ranked.get(1).unwrap(),
            &Entity::from(&Funder::new("heavenly ltd".into(), FunderKind::Company),)
        );
use crate::domain::models::entity_search::{Entity, EntitySearchError, EntitySearchRequest};

/// Allows users to search the databse using free text.
pub trait EntitySearchService: Clone + Send + Sync + 'static {
    /// Returns entities based on free text search
    fn search_entities(
        &self,
        req: &EntitySearchRequest,
    ) -> impl Future<Output = Result<Vec<Entity>, EntitySearchError>> + Send;
}
//! Possible entity search errors

use crate::domain::{
    models::entity_search::EntitySearchError,
    repositories::{
        funder_repository::FunderRepoError, parliament_member_repository::ParliamentMemberRepoError,
    },
};

impl From<ParliamentMemberRepoError> for EntitySearchError {
    fn from(value: ParliamentMemberRepoError) -> Self {
        match value {
            ParliamentMemberRepoError::DatabaseError(err) => Self::UnexpectedError(err),
        }
    }
}

impl From<FunderRepoError> for EntitySearchError {
    fn from(value: FunderRepoError) -> Self {
        match value {
            FunderRepoError::DatabaseError(err) => Self::UnexpectedError(err),
        }
    }
}
//! Collection of repositories for the `exposed` project

/// Access data about funders
pub mod funder_repository;

/// Access data about MPs
pub mod parliament_member_repository;

/// Pubilc API for UK Parliament  
pub mod parliament_api;

pub mod declaration_cleaning;
/// Store for cleaning parliament API data;
pub mod entity_ingestion;
use axum::{Router, routing::get};

use crate::{
    domain::services::entity_search::EntitySearchService,
    inbound::http::{handlers, state::AppState},
};

/// Routes for the exposed application
pub fn routes<E: EntitySearchService>() -> Router<AppState<E>> {
    Router::new().route("/search", get(handlers::search_entities))
}
use axum::{
    extract::{Query, State},
    http::StatusCode,
};
use serde::{Deserialize, Serialize};

use crate::{
    domain::{
        models::entity_search::{Entity, EntitySearchError, EntitySearchRequest},
        services::entity_search::EntitySearchService,
    },
    inbound::http::{error::ApiError, state::AppState, success::ApiSuccess},
};

#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct SearchEntitiesHttpRequest {
    term: String,
    max_entries: u8,
    strictness: Option<f32>,
}

impl SearchEntitiesHttpRequest {
    /// Converts the HTTP request body into a domain request.
    fn try_into_domain(self) -> Result<EntitySearchRequest, EntitySearchError> {
        match self.strictness {
            Some(s) => EntitySearchRequest::new_with_strictness(self.term, self.max_entries, s),
            None => EntitySearchRequest::new_strict(self.term, self.max_entries),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct SearchEntityResponseData {
    entities: Vec<SearchEntity>,
}

impl From<&[Entity]> for SearchEntityResponseData {
    fn from(value: &[Entity]) -> Self {
        let entities = value.iter().map(SearchEntity::from).collect();
        Self { entities }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct SearchEntity {
    name: String,
    kind: String,
    funder_kind: Option<String>,
}

impl From<&Entity> for SearchEntity {
    fn from(value: &Entity) -> Self {
        Self {
            name: value.name().to_string(),
            kind: value.kind().to_string(),
            funder_kind: value.funder_kind().map(String::from),
        }
    }
}

impl From<EntitySearchError> for ApiError {
    fn from(value: EntitySearchError) -> Self {
        match value {
            EntitySearchError::InvalidTerm(_)
            | EntitySearchError::InvalidStrictness(_)
            | EntitySearchError::TooFewEntries => Self::UnprocessibleEntity(value.to_string()),
            EntitySearchError::UnexpectedError(_) => Self::InternalServerError,
        }
    }
}

pub async fn search_entities<E: EntitySearchService>(
    State(state): State<AppState<E>>,
    Query(query): Query<SearchEntitiesHttpRequest>,
) -> Result<ApiSuccess<SearchEntityResponseData>, ApiError> {
    let domain_req = query.try_into_domain()?;
    state
        .entity_search_service
        .search_entities(&domain_req)
        .await
        .map_err(ApiError::from)
        .map(|ref entities| ApiSuccess::new(StatusCode::OK, entities.as_slice().into()))
}
use axum::{
    Json,
    http::StatusCode,
    response::{IntoResponse, Response},
};
use serde::Serialize;

/// Generic success message
pub struct ApiSuccess<S: Serialize> {
    code: StatusCode,
    response: S,
}

impl<S: Serialize> ApiSuccess<S> {
    /// Creates new instance
    pub const fn new(code: StatusCode, response: S) -> Self {
        Self { code, response }
    }
}

impl<S: Serialize> IntoResponse for ApiSuccess<S> {
    fn into_response(self) -> Response {
        (self.code, Json(self.response)).into_response()
    }
}

