            "
            SELECT  
                f.funder_name as name,
                f.funder_kind as kind,
                f.company_number,
                word_similarity($1, f.funder_name) as similarity_score,
                row_number() OVER (ORDER BY word_similarity($1, f.funder_name) DESC) as rank
